llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C26"],
      "claim": "Zalcitabine, a closely related polar cytidine nucleoside analogue, showed 88% absolute oral bioavailability in a patient after an oral solution, demonstrating that small polar nucleosides can be well absorbed and exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "In fasting patients, the purine nucleoside ddA/ddl given as a solution with antacid had an oral bioavailability of 38% ± 15%, directly supporting F ≥ 20% for a similar purine nucleoside under fasting conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Didanosine, a related purine nucleoside, had a median fasting F of 0.28 at the 50 mg/m² dose, which is above the 20% threshold and supports high oral bioavailability classification in the fasted state.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "The fluorinated pyrimidine nucleoside OGT 719 achieved about 25% oral bioavailability in patients, showing that even polar nucleoside analogues with permeability limitations can still meet the F ≥ 20% criterion.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a polar guanine nucleoside analogue, and the most transferable experimental evidence comes from closely related nucleoside analogues. Zalcitabine, didanosine/ddA, and OGT 719 all show oral bioavailability values at or above 20%, including under fasting conditions. The weight of direct nucleoside evidence therefore supports a high prediction for F ≥ 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the exact query molecule is present in the provided evidence.",
    "Didanosine fed-state values fall below 20%, but the query condition is fasted, so those records are not directly contradictory.",
    "Potential differences in active transport, metabolism, or prodrug behavior between guanine and other nucleobase analogues are not directly measured."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C26"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "nucleoside analogue oral bioavailability"
    }
  ],
  "revision_action": "initial"
}

